    if (mk === 'spreads') { m = s.match(/^(.*?)\s+([+\-]\d+(?:\.\d+)?)$/); return m ? { selection_raw: m[1], line: +m[2] } : { selection_raw: s, line: null }; }
    if (mk === 'h2h') return { selection_raw: s.replace(/\s+ML$/, ''), line: null };
    m = s.match(/^(.*?)\s+([+\-]?\d+(?:\.\d+)?)$/);
